// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":3112,"question":"إذا كانت المرأة متضررة بالحمل فهل يجوز أن تسوّي عملية لإزالة مبايض الحمل ونحو ذلك؟","title":"هل يجوز تعقيم المرأة المتضررة بالحمل؟","answer":"الجواب: إذا كان عليها ضرر بيّن؛ فيُسْتَشار الطبيبات الخاصات والأطباء الخاصون، إذا كان الضرر بينًا؛ فلا بأس بربط الرحم.\nس: إزالته؟\nالشيخ: لا بد من تحقق الضرر الذي لا يُحتمل.\nس: إذا تحقق ذلك هل يُزال الرحم؟\nالشيخ: لا بأس؛ يُزال أو يُربط.","link":"https://binbaz.org.sa/fatwas/23272/هل-يجوز-تعقيم-المراة-المتضررة-بالحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا كانت المرأة متضررة بالحمل.mp3","categories":["تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":3703,"question":"تحديد النسل؟","title":"ما حكم تحديد النسل؟","answer":"الجواب: ما ينبغي تحديد النسل إلا إذا دعت الحاجة والمصلحة لذلك بصفة مؤقتة.\nس: [منع] تحديد النسل للتحريم؟\nالشيخ: الأقرب أنه للتحريم؛ لأن الأمة مطلوب منها أن تجتهد في تكثيرها ووجود النسل والعفة، فأقل أحواله الكراهة، لكن ظاهر الأدلة المنع.","link":"https://binbaz.org.sa/fatwas/23893/ما-حكم-تحديد-النسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تحديد النسل.mp3","categories":["الحكم على الأحاديث","تنظيم الحمل وموانعه"]},{"id":3704,"question":"الحديث الضعيف في المنع أو في الجواز؟ الحديث الضعيف في العزل؟","title":"الحكم على حديث النهى عن العزل إلا بإذن","answer":"الجواب: حديث أن الرسول ﷺ نهى أن يعزل الرجل إلا بإذن الحرة رواه أحمد وفي إسناده رجل مجهول، فيه النهي عن العزل عن الحرة إلا بإذنها؛ لكن المعنى صحيح من حيث المعنى؛ لأن لها حقًّا في الولد، هما شركاء في الولد.","link":"https://binbaz.org.sa/fatwas/23894/الحكم-على-حديث-النهى-عن-العزل-الا-باذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم على حديث أن الرسول نهى أن يعزل الرجل إلا بإذن الحرة.mp3","categories":["الحقوق الزوجية","تنظيم الحمل وموانعه"]},{"id":3705,"question":"إذا كان بين الزوج والزوجة أمراض وراثية وأوصى الأطباء أنه إذا أتى ولد فقد يكون مريضًا، ما الحكم في ابتغاء الولد؟","title":"هل يجوز منع الإنجاب بسبب أمراض وراثية؟","answer":"الجواب: لا حرج، الأطباء يخطؤون ويصيبون، الأطباء ما يُعتمد عليهم.","link":"https://binbaz.org.sa/fatwas/23895/هل-يجوز-منع-الانجاب-بسبب-امراض-وراثية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ابتغاء الولد إذا كان بين الزوج والزوجة أمراض وراثية.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":4561,"question":"حبوب منع الحمل؟","title":"ما حكم استعمال حبوب منع الحمل؟","answer":"الجواب: فيها تفصيل: إذا كانت لضرورةٍ فلا بأس، وإلا ينبغي تركها.\nس: ما الضَّرورة؟\nج: مرض، أو تربية الأولاد الصغار إن كثروا عليها، أو ..... يعني هناك آلام.\nس: إذا كان عندها طفلٌ واحدٌ؟\nج: الظاهر ما يُكلّف، ما ينبغي تعاطي الحبوب، يعني إذا كثر الأولاد عليها وتقاربوا فصارت –يعني- تربيتهم تشقّ عليها.\nس: كم؟\nج: الله أعلم، ما في حدّ محدود، لكن المراد يعني مُراعاة .....، ومدته سنة أو سنتين، مدة الرضاع إذا كان ما فيه ضرر، إذا قرر الطبُّ أنَّ ما فيه ضرر.","link":"https://binbaz.org.sa/fatwas/24843/ما-حكم-استعمال-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم استعمال حبوب منع الحمل.mp3","categories":["تنظيم الحمل وموانعه","الطب والتداوي"]},{"id":5183,"question":"هل يجوز منع الحمل بسبب الرضاعة؛ لأنها لو حملت انقطع اللبنُ؟","title":"هل يجوز منع الحمل بسبب الرضاع؟","answer":"الجواب: هذا شيء بين الزوج وزوجته، فإذا كانت تُرضع، واصطلح هو وإياها على أنه لا يُجامعها خوفًا من الحمل، أو تتعاطى الحبوب المانعة حتى لا تحمل؛ لأجل بقاء اللبن للرضيع والعناية بتربيته؛ فلا حرج إن شاء الله، فتعاطي حبوب المنع من الحمل لمصلحة الطفل، أو لمصلحة الأم؛ لأنه يضرُّها الحمل، أو لأسبابٍ أخرى وجيهة لا محذور فيها؛ لا بأس. أما كونه يمتنع من الجماع فقد يضرُّه هذا، وقد يضرُّها هذا، وقد يُفضي إلى شرٍّ عظيمٍ عليهما جميعًا من جهة عدم الجماع، فربما أطلق بصره، وربما وقع في الفاحشة، وهي كذلك، لكن الأولى أن يُجامعها ويتصل بها، وتتعاطى الشيء الذي يمنع الحمل إذا كان يخشى من الحمل على الطفل الذي عندهما. وبالإمكان أن يُعطى الطفل من الحليب الذي يتعاطاه الناسُ، ويُفطم عن ثدي أمه، إذا اصطلحا على ذلك فلا بأس، إذا اتفق الزوجُ والزوجة على فطامه على لبنها وتربيته بشيءٍ آخر من الألبان المُجففة وغير ذلك فلا بأس؛ لأنَّ الله قال: فَإِنْ أَرَادَا فِصَالًا عَنْ تَرَاضٍ مِنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا [البقرة:233].","link":"https://binbaz.org.sa/fatwas/30120/هل-يجوز-منع-الحمل-بسبب-الرضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 145.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":5230,"question":"هل يجوز للمرأة أن تُؤخِّر الحملَ بواسطة وسائل منع الحمل بحجة إكمال الدراسة أو الإرضاع؟ وهل يجوز دعاء الله بأن يمنع الحملَ لهذه الأسباب؟","title":"حكم تأخير الحمل من أجل الدراسة أو الإرضاع","answer":"الجواب: الذي يظهر لنا من الشرع المُطهر أنه لا ينبغي للمرأة: لا منع الحمل بالحبوب، ولا غيرها، ولا بالدعاء، ولا بغير ذلك؛ لأنَّ الحمل قد يكون فيه خيرٌ عظيمٌ ومصالح جمَّة، وقد صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: تزوَّجوا الولود الودود، فإني مُكاثرٌ بكم الأمم يوم القيامة، ولأن المسلم في حاجةٍ إلى المزيد، والرغبة مطلوبةٌ في زيادة المسلمين -زيادة عددهم- ثم هذا أيضًا ينفع الوالدين، وجود الولد ينفعهما في الدنيا والآخرة، فلا ينبغي التَّسبب في منعه، لا بالحبوب، ولا بغير ذلك. لكن إذا دعت قالت: \"اللهم قدّر الأصلح، اللهم إن كان حملي أصلح فيسر ذلك، وإن كان ليس بأصلح فاكفني شرَّه\" وما أشبهه فلا بأس، فهو شيءٌ معلَّقٌ على علم الله . أما أن تقول: \"اللهم امنع عني الحمل مطلقًا\" فهذا ما ينبغي، أو تفعل ما يمنعه كذلك إلا لعلَّةٍ ذكرها أهلُ العلم؛ إذا كان معها مرضٌ قرر الأطباءُ أنه يضرُّها الحمل وعليها خطرٌ منه؛ فهذا لا بأس، عذرٌ لها أن تتعاطى ما يمنعه إذا كان عليها خطرٌ من الحمل، أو تراكم الأولاد عليها، وشقَّت عليها التربية؛ لأنهم صغار، وحملت هذا على هذا؛ جاز لها أن تتعاطى بعض الموانع في السنة الأولى والثانية أيام الرضاع، حتى تستعين بذلك على التربية الصَّالحة، وإن تركت واستعانت بالله وتركت هذا الأمر فذلك خيرٌ لها وأبرك وأفضل.","link":"https://binbaz.org.sa/fatwas/30174/حكم-تاخير-الحمل-من-اجل-الدراسة-او-الارضاع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 268.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":5642,"question":"تعاطي بعض حبوب منع الحمل يُقاس على العزل؟","title":"ما حكم تعاطي حبوب منع الحمل؟","answer":"الجواب: لا، فيه تفصيل، هو من الأسباب، فيه تفصيل:  إذا دعت الحاجةُ إليه لا بأس: إما مرضها، أو مرض رحمها، أو خطر عليها، أو توالي الأولاد عليها حتى لا تستطيع التربية، فتأخذ بعض الحبوب وقتًا ما، إذا كان ما فيها ضرر، وإذا قرر الأطباء أن ما فيها ضرر، ووافق الزوج. ومثلما كانت الأسباب لا تمنع، حتى الحبوب لا تمنع، إذا أراد اللهُ شيئًا تمَّ.[1]","link":"https://binbaz.org.sa/fatwas/31652/ما-حكم-تعاطي-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 003.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":5825,"question":"إذا اتفقت المرأة على عدم الإنجاب باستعمال حبوب منع الحمل، فما حكم ذلك؟","title":"استعمال حبوب منع الحمل لعدم الإنجاب","answer":"الجواب:  استعمال حبوب منع الحمل هذا على كل حال فيه تفصيل، إن دعت لها الحاجة؛ لأن الزوجة تحمل هذا على هذا، ويضرها ذلك؛ فلا بأس باستعمال الحبوب مع العناية بعدم ضررها، وأن يكون ذلك عن إشراف الطبيب، وعن معرفة تتعاطى ذلك، ما تحتاج إليه حتى يمضي مدة كسنة، أو سنتين، أو أكثر، ثم تدع الحبوب حتى تحمل، وحتى تنتفع هي وزوجها، والمسلمون، فلا ينبغي أن تكون الحبوب مستمرة؛ بل بقدر الحاجة فقط، أو لكونها مريضة يضرها الحمل إذا حملت لا تلد إلا بعلميات، ومضرة، فتأخذ الحبوب لأجل هذه المضرة العظيمة، أو لأسباب أخرى شرعية. أما اعتيادها مطلقًا فلا ينبغي ذلك، بل هذا يضر المجتمع، ويضر الحكمة التي بينها الله -جل وعلا- على لسان رسوله محمد -عليه الصلاة والسلام- في الحث على الاستكثار من الأولاد؛ لتكثير الأمة، فإن الكفار، والمشركين يحبون أن يكثر هذا في الناس، يحبون أن يكثر فيهم تعاطي الحبوب؛ حتى يقل نسل المسلمين، وحتى يقل عددهم، وحتى يكثر عدد أعدائهم، هذا مطلوب للكفار، فلا ينبغي للمسلم أن يحقق طلبات الكفار باستعمال هذه الحبوب التي تضر المجتمع، وتقلل النسل، وتقلل أمة المسلمين، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1178/استعمال-حبوب-منع-الحمل-لعدم-الانجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_174.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":5826,"question":"إذا اتفقت المرأة على عدم الإنجاب باستعمال حبوب منع الحمل، فما حكم ذلك؟","title":"استعمال حبوب منع الحمل لعدم الإنجاب","answer":"الجواب:  استعمال حبوب منع الحمل هذا على كل حال فيه تفصيل، إن دعت لها الحاجة؛ لأن الزوجة تحمل هذا على هذا، ويضرها ذلك؛ فلا بأس باستعمال الحبوب مع العناية بعدم ضررها، وأن يكون ذلك عن إشراف الطبيب، وعن معرفة تتعاطى ذلك، ما تحتاج إليه حتى يمضي مدة كسنة، أو سنتين، أو أكثر، ثم تدع الحبوب حتى تحمل، وحتى تنتفع هي وزوجها، والمسلمون، فلا ينبغي أن تكون الحبوب مستمرة؛ بل بقدر الحاجة فقط، أو لكونها مريضة يضرها الحمل إذا حملت لا تلد إلا بعلميات، ومضرة، فتأخذ الحبوب لأجل هذه المضرة العظيمة، أو لأسباب أخرى شرعية. أما اعتيادها مطلقًا فلا ينبغي ذلك، بل هذا يضر المجتمع، ويضر الحكمة التي بينها الله -جل وعلا- على لسان رسوله محمد -عليه الصلاة والسلام- في الحث على الاستكثار من الأولاد؛ لتكثير الأمة، فإن الكفار، والمشركين يحبون أن يكثر هذا في الناس، يحبون أن يكثر فيهم تعاطي الحبوب؛ حتى يقل نسل المسلمين، وحتى يقل عددهم، وحتى يكثر عدد أعدائهم، هذا مطلوب للكفار، فلا ينبغي للمسلم أن يحقق طلبات الكفار باستعمال هذه الحبوب التي تضر المجتمع، وتقلل النسل، وتقلل أمة المسلمين، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1178/استعمال-حبوب-منع-الحمل-لعدم-الانجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_174.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":6108,"question":"هل يجوز العزل؟ وإذا دعت الحاجة إلى ذلك، هل الأهون استعمال حبوب منع الحمل، أو العزل؟","title":"حكم العزل واستخدام الحبوب المانعة للحمل","answer":"الجواب: يجوز العزل، وتركه أفضل، وإذا دعت إليه الحاجة؛ فلا بأس، وتجوز الحبوب حبوب منع الحمل إذا دعت إليها الحاجة مثل: كون المرأة تحمل هذا على هذا بسرعة، أو يضرها الحمل، فيحب أن يجعل بينهما وقتًا؛ لعلها تسلم من الضرر، إذا دعت إليه الحاجة على إشراف الطبيب، ولم يكن عليها ضرر في ذلك؛ فلا بأس. والعزل كونه يجمع، ثم عند إحساسه بخروج المني يفصل ذكره، خروج المني إلى الخارج؛ لئلا تحمل إذا دعت الحاجة إلى ذلك؛ فلا بأس، قال جابر : \"كنا نعزل والقرآن ينزل، ولو كان شيئًا ينهى عنه لنهانا القرآن\" وفي لفظ آخر: \"وبلغ ذلك النبي ﷺ فلم ينهنا، عليه الصلاة والسلام\".","link":"https://binbaz.org.sa/fatwas/1534/حكم-العزل-واستخدام-الحبوب-المانعة-للحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_464.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":6438,"question":"هل يجوز العزل بغرض تربية الطفل في حالة الرضاعة الصناعية لمرض في ثدي أمه؟","title":"هل يجوز العزل بغرض تربية الطفل؟","answer":"الجواب: الأصل العزل جائز هذا هو الأصل، الأصل جائز يجوز العزل للمصلحة الشرعية، وللأسباب التي يتفق عليها الزوجان، لكن ينبغي ألا تكون طويلة؛ لأن العزل الكثير قد يسبب مشاكل على الجميع، لكن إذا كان في مدة قليلة، مثل ما جاء عن النبي ﷺ قال جابر: \"كنا نعزل والقرآن ينزل، ولو كان شيئًا ينهى عنه لنهانا عنه القرآن\" فالعزل موجود في عهده -عليه الصلاة والسلام- ولم ينه عنه.","link":"https://binbaz.org.sa/fatwas/2191/هل-يجوز-العزل-بغرض-تربية-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_816.mp3","categories":["شروط وأركان الزواج","تنظيم الحمل وموانعه"]},{"id":6451,"question":"هل يجوز العزل بغرض تربية الطفل في حالة الرضاعة الصناعية لمرض في ثدي أمه؟","title":"هل يجوز العزل بغرض تربية الطفل؟","answer":"الجواب: الأصل العزل جائز هذا هو الأصل، الأصل جائز يجوز العزل للمصلحة الشرعية، وللأسباب التي يتفق عليها الزوجان، لكن ينبغي ألا تكون طويلة؛ لأن العزل الكثير قد يسبب مشاكل على الجميع، لكن إذا كان في مدة قليلة، مثل ما جاء عن النبي ﷺ قال جابر: \"كنا نعزل والقرآن ينزل، ولو كان شيئًا ينهى عنه لنهانا عنه القرآن\" فالعزل موجود في عهده -عليه الصلاة والسلام- ولم ينه عنه.","link":"https://binbaz.org.sa/fatwas/2191/هل-يجوز-العزل-بغرض-تربية-الطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_816.mp3","categories":["شروط وأركان الزواج","تنظيم الحمل وموانعه"]},{"id":7906,"question":"أيضاً يقولان: هل يجوز تحديد الإنجاب في الحياة الزوجية؟","title":"حكم تحديد الإنجاب في الحياة الزوجية","answer":"الجواب: لا يجوز، بل يجب على المرأة أن تجتنب هذا الشيء، إلا عند الضرورة لا بأس بتعاطي بعض الحبوب أو بعض الأشياء التي تمنع الحمل وقتاً ما، وأما منعه بالكلية فلا، هذا يخالف مقتضى الشرع المطهر، فإن الشرع المطهر يتشوف لكثرة النسل، والرسول ﷺ دعا إلى ذلك وقال: إني مكاثر بكم الأمم يوم القيامة، فلا ينبغي التعرض لقطع النسل.\nولكن إذا دعت الضرورة إلى تأخير الحمل بعض الوقت لتربية الأولاد؛ لأنها تحمل على هذا، فتحتاج إلى أن تؤخر الحمل إلى وقت ما حتى تستطيع تربية الموجودين فلا بأس، مثل تأخذ حبوب تمنع الحمل سنة أو سنتين حتى تفطم، وحتى تتفرغ للحمل الجديد، هذا لا بأس به إن شاء الله، ولا حرج فيه.","link":"https://binbaz.org.sa/fatwas/5396/حكم-تحديد-الانجاب-في-الحياة-الزوجية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06205.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":8654,"question":"هذه رسالة وردتنا من غانا، من سائلة سمت نفسها بابة يندي تقول: أصحاب الفضيلة حفظكم الله تعالى وجزاكم الله خير! لكنني سمعت في إحدى حلقات البرنامج عن جواز استعمال الحبوب الذي يمنع الحمل، سمعت هذه الإجابة مرتين، مرة سأل عنها واحد مهندس مصري الجنسية ويقولون: إنه يجوز استعمال الحبوب منع الحمل، بالرغم أنني لا أعلم ولا أسمع دليل بجواز ذلك من القرآن والسنة ولا أقوال جمهور العلماء، وأنتم تعلمون أن هذه من أعمال النصارى والكفار؛ لأنهم هم الذين صنعوها وأرسلوها إلى المسلمين ليقللوا أولاد المسلمين، والرسول صلى الله عليه وسلم حضنا على كثرة الولد في حديث أنس بن مالك : كان رسول الله ﷺ يأمرنا بالباءة وينهى عن التبتل ويقول: تزوجوا الولود الودود فإني مكاثر بكم الأنبياء يوم القيامة رواه أحمد ، أفتونا أفادكم الله؟","title":"ترغيب الإسلام في كثرة الولد","answer":"الجواب: قد أحسنت بارك الله فيك، ولا شك أن استعمال الحبوب من المسلمين لمنع الأولاد لا شك أنه من الدعاية العظيمة للنصارى، فـالنصارى يدعون إلى هذا الأمر لتقليل أولاد المسلمين، ولكن ليس كل ما يدعون إليه يكون محرماً، فإذا دعوا إلى شيء أباحه الشرع فدعوتهم لا تضرنا، وإذا دعوا إلى شيء حرمه الشرع فالواجب تركه، وإذا دعوا إلى شيء أباحه الشرع فلا بأس.\nفالحبوب فيها تفصيل: فإذا دعت إليها الحاجة؛ لأن المرأة مريضة لا تتحمل الحمل، أو مصابة في رحمها بشيء يضرها الحمل، أو يسبب موتها وقتلها فلا بأس بترك الحمل، ولا بأس بتعاطي الحبوب المانعة من الحمل، وهكذا إذا كانت كثيرة الأولاد، قد كثروا وتتابعوا عليها ويشق عليها التربية لهم لكثرتهم، فإنها يجوز لها أن تتعاطى الحبوب بإذن زوجها لمدة يسيرة كالسنة والسنتين أيام الرضاعة، حتى يخف عليها الأمر ويسهل عليها القيام بالتربية، والدليل على ذلك ما ثبت في الأحاديث الصحيحة عن رسول الله ﷺ أنه أذن في العزل، قال جابر ﷺ: كنا نعزل والقرآن ينزل، ولو كان شيئاً ينهى عنه لنهانا عنه القرآن متفق على صحته، وفق الله الجميع. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6795/ترغيب-الاسلام-في-كثرة-الولد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21310.mp3","categories":["تنظيم الحمل وموانعه"]},{"id":9437,"question":"وأولى رسائل هذه الحلقة وردت من عبدالسميع حسان عبدالسميع الشوبكي من مصر محافظة الشرقية، والأخ عبدالسميع يطلب أن نبعث له الجواب خطياً وهذا ما لا يمكننا في هذا البرنامج، وننبهه هو وغيره من الإخوة الذين يرغبون في ذلك بأن عليهم أن يكتبوا عناوينهم واضحة في رسائلهم، وأن يوجهوا الرسائل إلى الرئاسة العامة للبحوث العلمية والإفتاء والدعوة والإرشاد، فهي الجهة التي تقوم -بإذن الله- بإرسال الأجوبة إليهم خطياً، أما ما يصل إلى الإذاعة فإننا نحاول عرضه ما أمكن عبر الأثير وهذا قدر استطاعتنا نسأل الله للجميع التوفيق، رسالة الأخ عبدالسميع حسان يقول فيها: ما حكم استعمال حبوب منع الحمل، وما حكم -أيضاً- منع الحمل بطريقٍ آخر غير الحبوب كاللوالب وغيرها، أفيدونا أفادكم الله؟","title":"حكم استعمال اللولب وحبوب منع الحمل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله سبحانه شرع لعباده النكاح لما فيه من الفائدة العظيمة، لغض البصر وحفظ الفرج، ولما فيه من تكثير الأمة، وإيجاد النسل، ولهذا قال عليه الصلاة والسلام: تزوجوا الولود الودود، فإني مكاثر بكم الأمم يوم القيامة، فالسنة للمؤمن أن يبادر بالزواج، وهكذا المؤمنة وأن يجتهدا في الإنجاب وأسباب الإنجاب لتكثير الأمة ولوجود أولاد يرجى فيهم الخير من الذكور والإناث، وعليهما أن يجتهدا في أسباب صلاح الأولاد، وقيامهم بما يجب عليهم لله سبحانه ولعباده ولوالديهم، لكن إذا دعت الحاجة لمنع الحمل فلا بأس، كأن تكون المرأة مريضة يشق عليها الحمل لمرض في رحمها أو مرض قرر الأطباء أنه يضره الحمل، فتأخذ الحبوب أو الإبر لمنع الحمل، كذلك إذا كانت المرأة لديها أولاد كثيرون تلد هذا مع هذا، وهذا على هذا، ويشق عليها التربية إلا بين وقت وآخر، فلا مانع أن تأخذ الحبوب لمنع الحمل أو عملاً آخر لمنع الحمل في مدة الرضاع سنة سنتين حتى تستطيع أن تقوم بالتربية، وتقوى على مئونة التربية، أما منع الحمل من غير علة فظاهر الأدلة الشرعية أنه لا يجوز، وإنما يجوز عند الحاجة كالعزل، يعزل الرجل عن امرأته للحاجة، والله ولي التوفيق. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7599/حكم-استعمال-اللولب-وحبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23901.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9747,"question":"وهذه رسالة وردت إلينا من المرسل: مصطفى عبدالقادر من الجزائر ومقيم بليبيا، يقول في رسالته: ما حكم المرأة التي تجهض حملها، وله من العمر شهران، وهل يجوز قسمة التركة قبل أن يوضع الحمل، أفيدونا أفادكم الله؟","title":"حكم إجهاض الجنين","answer":"الجواب: الإجهاض فيه مضار كثيرة ولا ينبغي، والصواب من قولي العلماء فيه أنه لا يجوز، هذا قبل التخلق، فإذا تخلق ونفخت فيه الروح حرم صار قتل، لكن قبل أن تنفخ فيه الروح قبل الأربعة الأشهر لا يجوز، لما فيه من العدوان على نفس قد انعقدت أسبابها، ولما فيه أيضاً من العدوان على تكثير النسل، والشيء الذي أحبه الله وشرعه  لعباده وهو تكثير النسل، فهذا يزيله ويقلله ويقطعه بهذه العملية، فالإجهاض في هذه الحالة غير جائز.\nاللهم إلا أن يكون في الأربعين الأولى، فقد أجازه قوم من أهل العلم في الأربعين الأولى مادام نطفة، إذا دعت الحاجة إلى ذلك فلا بأس، وتركه أولى.\nأما بعد الأربعين فيحرم، وبعد نفخ الروح يكون قتلاً نسأل الله العافية. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7921/حكم-اجهاض-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25612.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9752,"question":"هذا السؤال الثاني له وهو متعلق أيضًا بالسؤال الأول يقول: ما الحكم في تنظيم النسل مثلًا كل خمس سنوات، وماذا علي أنا كزوج إذا نصحت زوجتي بعدم ذلك ولكنها ترفض الحمل نهائيًا بعد طفلنا الذي بلغ من عمره أربع سنوات بحجة أنها في غنى عن تعب الحمل والوضع، وتخشى من ظروف قد تحدث لي أو لها أو لنا معًا فيتركون الأولاد وحدهم، هذا ما تذكره دائمًا إذا نصحتها وخوفتها بأمر الله وأن عليها أن تخضع لقضائه، وفي النهاية تقول لي: إما العمل وعدم الإنجاب أو أن تطلقني، فماذا علي شرعًا تجاه إصرارها في ذلك؟","title":"حكم تنظيم النسل لمدة خمس سنوات","answer":"الجواب: عليكما جميعًا أن تتعاونا على البر والتقوى وأن تنصحها كثيرًا في عدم منع الحمل المدة المذكورة؛ لأن الرسول ﷺ رغب في النسل ورغب في تكثير الأمة، وقال عليه الصلاة والسلام: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة، فينبغي لها أن تخضع لهذا الأمر وأن تحسن ظنها بربها وأن تجتهد في تربيتهم مع التربية الشرعية وأن تتعاون في ذلك، أما تأخيرها الحمل لمدة خمس سنين أو أكثر هذا لا ينبغي والأظهر من الأدلة منعه، لكن إذا كان سنة أو سنتين للتربية يعني مدة الرضاع فلا حرج إن شاء الله في السنة أو السنتين التي هي مدة الرضاع أو أقل منها للحاجة إلى تربية الأولاد وأن لا يكثروا عليها فتعجز عن تربيتهم فلا حرج، فعليك أن تجتهد في إقناعها والمشورة عليها ونصيحتها لعل الله يهديها حتى ترجع إلى الصواب، أما الطلاق فلا ينبغي أن تعجل في طلاقها ولكن تحاول أنها تقتنع بهذا الأمر. نعم.\nالمقدم: وهل يجوز لها يا سماحة الشيخ أن تقول: إما أن تعمل ولا تنجب أو يطلقها؟\nالشيخ: لا يجوز لها ذلك، ليس لها أن تطلب بالطلاق بغير علة، وهذه ليست علة مسوغة لطلب الطلاق بل هو ناصح لها وقوله أصوب وعملها هي ليس بطيب، ينبغي لها بل الواجب عليها أن تسمع لزوجها وأن تطيع لزوجها وأن تمكنه من أسباب تكثير النسل بترك تعاطي ما يمنع الحمل.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7912/حكم-تنظيم-النسل-لمدة-خمس-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19605.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9755,"question":"هذا السؤال الثاني له وهو متعلق أيضًا بالسؤال الأول يقول: ما الحكم في تنظيم النسل مثلًا كل خمس سنوات، وماذا علي أنا كزوج إذا نصحت زوجتي بعدم ذلك ولكنها ترفض الحمل نهائيًا بعد طفلنا الذي بلغ من عمره أربع سنوات بحجة أنها في غنى عن تعب الحمل والوضع، وتخشى من ظروف قد تحدث لي أو لها أو لنا معًا فيتركون الأولاد وحدهم، هذا ما تذكره دائمًا إذا نصحتها وخوفتها بأمر الله وأن عليها أن تخضع لقضائه، وفي النهاية تقول لي: إما العمل وعدم الإنجاب أو أن تطلقني، فماذا علي شرعًا تجاه إصرارها في ذلك؟","title":"حكم تنظيم النسل لمدة خمس سنوات","answer":"الجواب: عليكما جميعًا أن تتعاونا على البر والتقوى وأن تنصحها كثيرًا في عدم منع الحمل المدة المذكورة؛ لأن الرسول ﷺ رغب في النسل ورغب في تكثير الأمة، وقال عليه الصلاة والسلام: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة، فينبغي لها أن تخضع لهذا الأمر وأن تحسن ظنها بربها وأن تجتهد في تربيتهم مع التربية الشرعية وأن تتعاون في ذلك، أما تأخيرها الحمل لمدة خمس سنين أو أكثر هذا لا ينبغي والأظهر من الأدلة منعه، لكن إذا كان سنة أو سنتين للتربية يعني مدة الرضاع فلا حرج إن شاء الله في السنة أو السنتين التي هي مدة الرضاع أو أقل منها للحاجة إلى تربية الأولاد وأن لا يكثروا عليها فتعجز عن تربيتهم فلا حرج، فعليك أن تجتهد في إقناعها والمشورة عليها ونصيحتها لعل الله يهديها حتى ترجع إلى الصواب، أما الطلاق فلا ينبغي أن تعجل في طلاقها ولكن تحاول أنها تقتنع بهذا الأمر. نعم.\nالمقدم: وهل يجوز لها يا سماحة الشيخ أن تقول: إما أن تعمل ولا تنجب أو يطلقها؟\nالشيخ: لا يجوز لها ذلك، ليس لها أن تطلب بالطلاق بغير علة، وهذه ليست علة مسوغة لطلب الطلاق بل هو ناصح لها وقوله أصوب وعملها هي ليس بطيب، ينبغي لها بل الواجب عليها أن تسمع لزوجها وأن تطيع لزوجها وأن تمكنه من أسباب تكثير النسل بترك تعاطي ما يمنع الحمل.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7912/حكم-تنظيم-النسل-لمدة-خمس-سنوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19605.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9910,"question":"يقول هذا السائل: (أ. خ. ق) من الأردن: رجل متزوج وعندي ستة أولاد وبنت واحدة وأرغب في أن أضع حد للإنجاب الآن حيث أنني لا أرغب في إنجاب المزيد من الأولاد علمًا بأن دخلي المادي محدود، فما حكم الشرع في نظركم في هذا الموضوع، وهل يجوز لي أن أنظم الإنجاب؟ جزاكم الله خيرًا يا سماحة الشيخ!","title":"عنده سبعة أولادولا يرغب في إنجاب المزيد","answer":"الجواب: المشروع عدم التحديد؛ لأن الشارع يرغب في المزيد من النسل، وفي تكثير الأمة يقول ﷺ في الحديث الصحيح: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة فالمشروع لك -يا أخي- عدم التحديد، وأن تصبر، وأن ترغب في المزيد تسأل ربك الصلاح فربما نفعك الله بهم، فأنت على خير عظيم تحسن تربيتهم وتقوم عليهم، وتسأل الله لهم الصلاح وهو خير لك من التحديد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8078/عنده-سبعة-اولاد-ولا-يرغب-في-انجاب-المزيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_273/27322.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9945,"question":"هذا السائل من مصر أيضاً يسأل: ما حكم الإسلام في تحديد النسل؟","title":"ما حكم الإسلام في تحديد النسل؟","answer":"الجواب: تحديد النسل فيه تفصيل: الأصل أنه لا يحدد النسل ولا يجوز، وليس لدولة أو أي إنسان أن يتدخل في تحديد النسل، بل هذا يترك إلى الناس وليس لدولة أن تقول: يجب أن يكون النسل أربعة أو خمسة أو ثلاثة، لا، هذا حرام ومنكر وظلم، لا يجوز، لكن الإنسان إذا كان على زوجته مشقة لمرض في رحمها أو مرض بها يضرها الحمل بتقرير الأطباء جاز أن يؤجل الحمل إلى وقت آخر، حتى يأذن الأطباء في ذلك ويقولوا: إنه لا يضرها، وهكذا لو كانت تحمل هذا على هذا وكثر عليها الأولاد وشق عليها التربية؛ لكثرة الأولاد فلا مانع من تعاطي ما يحدد النسل لمدة سنة أو سنتين، حتى تستطيع التربية وحتى تتمكن من أداء ما يجب لأولادها من تربية وإحسان وملاحظة مثل مدة الرضاع سنتين أو سنة، تتعاطى ما يمنع الحمل حتى يحصل لها الفراغ لتربية أولادها الصغار، وأما تحديده مطلقاً فلا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8116/ما-حكم-الاسلام-في-تحديد-النسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26708.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9949,"question":"هذا السائل من مصر أيضاً يسأل: ما حكم الإسلام في تحديد النسل؟","title":"ما حكم الإسلام في تحديد النسل؟","answer":"الجواب: تحديد النسل فيه تفصيل: الأصل أنه لا يحدد النسل ولا يجوز، وليس لدولة أو أي إنسان أن يتدخل في تحديد النسل، بل هذا يترك إلى الناس وليس لدولة أن تقول: يجب أن يكون النسل أربعة أو خمسة أو ثلاثة، لا، هذا حرام ومنكر وظلم، لا يجوز، لكن الإنسان إذا كان على زوجته مشقة لمرض في رحمها أو مرض بها يضرها الحمل بتقرير الأطباء جاز أن يؤجل الحمل إلى وقت آخر، حتى يأذن الأطباء في ذلك ويقولوا: إنه لا يضرها، وهكذا لو كانت تحمل هذا على هذا وكثر عليها الأولاد وشق عليها التربية؛ لكثرة الأولاد فلا مانع من تعاطي ما يحدد النسل لمدة سنة أو سنتين، حتى تستطيع التربية وحتى تتمكن من أداء ما يجب لأولادها من تربية وإحسان وملاحظة مثل مدة الرضاع سنتين أو سنة، تتعاطى ما يمنع الحمل حتى يحصل لها الفراغ لتربية أولادها الصغار، وأما تحديده مطلقاً فلا يجوز. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8116/ما-حكم-الاسلام-في-تحديد-النسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_267/26708.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9957,"question":"هذه السائلة أيضاً تقول: في بعض المستشفيات أحياناً يواجهنا نوع من التوجيه إلى تقليل النسل، وإذا لوحظ على المرأة أنها قد ولدت أكثر من أربعة أطفال أو خمسة، فإن الطبيب المختص بأمراض النساء ينصحها ويقول في تكرارك للحمل خطر عليك، وفي هؤلاء كفاية، فما مدى صحة مثل هذا الكلام، وهل نستمع لنصائح هؤلاء الأطباء؟","title":"جواز إيقاف النسل بعض الوقت للحاجة","answer":"الجواب: تحديد النسل لا يجوز، ولا ينبغي أن يستمع لنصائح هؤلاء الأطباء، بل ينبغي للرجل والمرأة أن يستمرا في طلب النسل وتكثير الأولاد؛ لأن الشرع الإسلامي رغب في ذلك، والنبي ﷺ قال: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالرسول ﷺ رغب في إكثار النسل، وفي تكثير الأمة التي تعبد الله وحده وتتبع شريعته، ولعل الله يعطي الرجل والمرأة أولاداً صالحين، يشفعون لهم يوم القيامة، ويدعون لهم في الدنيا، وينفعون الأمة في دينها ودنياها، فلا ينبغي التحديد، بل لا يجوز التحديد إلا من علة، كالمرض الذي يصيب المرأة في رحمها، ويقرر الطبيب المختص بأنه لا حيلة في ذلك، وأن الحمل يضرها ويخشى عليها منه، أو كالأمراض العارضة التي يمكن أن تعالج بعدم الحمل وقتاً معيناً كسنة أو سنتين، أما تحديد النسل بأن يقتصر على أربعة أو ثلاثة أو خمسة ثم تتعاطى المرأة ما يقطع الحمل، هذا لا يجوز قد يموت هؤلاء، قد يموت الأربعة وقد يموت الخمسة، قد يموت أكثرهم فيندم الرجل وتندم المرأة غاية الندامة، الآجال بيد الله سبحانه وتعالى.\nفالحاصل: أنه لا يجوز تحديد النسل ولكن لا مانع من إيقاف النسل بعض الوقت للحاجة، كالمرض العارض للمرأة أو لرحمها، وكالأولاد الكثيرين الذين يشق عليها تربيتهم، فتأخذ ما يمنع الحمل سنة أو سنتين مدة الرضاع حتى تستعين بهذا على تربية أطفالها الصغار، أما المنع مطلقاً فهذا لا يجوز. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8124/جواز-ايقاف-النسل-بعض-الوقت-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26503.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":9966,"question":"هذه السائلة أيضاً تقول: في بعض المستشفيات أحياناً يواجهنا نوع من التوجيه إلى تقليل النسل، وإذا لوحظ على المرأة أنها قد ولدت أكثر من أربعة أطفال أو خمسة، فإن الطبيب المختص بأمراض النساء ينصحها ويقول في تكرارك للحمل خطر عليك، وفي هؤلاء كفاية، فما مدى صحة مثل هذا الكلام، وهل نستمع لنصائح هؤلاء الأطباء؟","title":"جواز إيقاف النسل بعض الوقت للحاجة","answer":"الجواب: تحديد النسل لا يجوز، ولا ينبغي أن يستمع لنصائح هؤلاء الأطباء، بل ينبغي للرجل والمرأة أن يستمرا في طلب النسل وتكثير الأولاد؛ لأن الشرع الإسلامي رغب في ذلك، والنبي ﷺ قال: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالرسول ﷺ رغب في إكثار النسل، وفي تكثير الأمة التي تعبد الله وحده وتتبع شريعته، ولعل الله يعطي الرجل والمرأة أولاداً صالحين، يشفعون لهم يوم القيامة، ويدعون لهم في الدنيا، وينفعون الأمة في دينها ودنياها، فلا ينبغي التحديد، بل لا يجوز التحديد إلا من علة، كالمرض الذي يصيب المرأة في رحمها، ويقرر الطبيب المختص بأنه لا حيلة في ذلك، وأن الحمل يضرها ويخشى عليها منه، أو كالأمراض العارضة التي يمكن أن تعالج بعدم الحمل وقتاً معيناً كسنة أو سنتين، أما تحديد النسل بأن يقتصر على أربعة أو ثلاثة أو خمسة ثم تتعاطى المرأة ما يقطع الحمل، هذا لا يجوز قد يموت هؤلاء، قد يموت الأربعة وقد يموت الخمسة، قد يموت أكثرهم فيندم الرجل وتندم المرأة غاية الندامة، الآجال بيد الله سبحانه وتعالى.\nفالحاصل: أنه لا يجوز تحديد النسل ولكن لا مانع من إيقاف النسل بعض الوقت للحاجة، كالمرض العارض للمرأة أو لرحمها، وكالأولاد الكثيرين الذين يشق عليها تربيتهم، فتأخذ ما يمنع الحمل سنة أو سنتين مدة الرضاع حتى تستعين بهذا على تربية أطفالها الصغار، أما المنع مطلقاً فهذا لا يجوز. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8124/جواز-ايقاف-النسل-بعض-الوقت-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_265/26503.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":10259,"question":"يذكر من الأشياء التي يقع الخلاف بسببها أنها امتنعت عن الحمل بعد أن أنجبت أربعة أطفال ثلاث بنات وولد، فما هو توجيهكم؟","title":"حكم امتناع المرأة عن الحمل لغير ضرورة","answer":"الجواب: الواجب عليها أن لا تمتنع وأن تترك تعاطي المانع من حبوب أو غيرها، إلا إذا كان هناك ضرر بين بتقدير الطبيب المختص، هذا لا حرج، وإلا فالواجب عليها السمع والطاعة لزوجها، ولعل الله يرزقهما مزيداً من الأولاد الصالحين، لا تمتنع ولا تتعاطى الشيء الذي يمنعها زوجها منه، من أسباب عدم الحمل، إلا إذا كان هناك ضرر بين بتقدير طبيب مختص أو أكثر فلا بأس، لقوله ﷺ: لا ضرر ولا ضرار. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8429/حكم-امتناع-المراة-عن-الحمل-لغير-ضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27909.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":10428,"question":"يسأل ويقول: ما حكم الإجهاض في الإسلام؟ وهل يجوز في مدة معينة، جزاكم الله خيراً؟","title":"حكم الإجهاض","answer":"الجواب: هذا فيه تفصيل، أمره عظيم، الإجهاض أمره عظيم وفيه التفصيل: إذا كان في الأربعين الأولى فالأمر فيه أوسع، إذا دعت الحاجة إلى الإجهاض لأن عندها أطفال صغار تربيهم ويشق عليها الحمل، أو لأنها مريضة يشق عليها الحمل فلا بأس بإسقاطه في الأربعين الأولى، أما في الأربعين الثانية بعد العلقة وفي الأربعين الثالثة المضغة هذا أشد، ليس لها إسقاطه إلا عند عذر شديد، مرض شديد، يقرر المختص أنه يضرها بقاؤه فلا مانع من إسقاطه في هذه الحالة، عند خوف الضرر الكبير.\nوأما بعد نفخ الروح فيه بعد الشهر الرابع فلا يجوز إسقاطه أبداً، بل يجب عليها أن تصبر وتتحمل حتى تلد إن شاء الله، إلا إذا قرر طبيبان أو أكثر مختصان ثقتان أن بقاءه يقتلها وسبب لموتها فلا بأس بتعاطي أسباب لإخراجه حذراً من موتها؛ لأن حياتها ألزم، عند الضرورة القصوى بتقرير طبيبين أو أكثر ثقات أن بقاءه يضرها، وأن عليها خطراً بالموت إذا بقي فلا بأس، إذا وجد ذلك بالشروط المذكورة فلا حرج في ذلك إن شاء الله، وهكذا لو كان مشوهاً تشويهاً يضرها لو بقي يكون خطر عليها، قرر طبيبان فأكثر أن هذا الولد لو بقي عليها خطر الموت لأسباب في الطفل، فهذا كله يجوز عند الضرورة إذا كان عليها خطر.. خطر الموت، بتقرير طبيبين أو أكثر مختصين ثقتين. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8598/حكم-الاجهاض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31706.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":10429,"question":"يسأل ويقول: ما حكم الإجهاض في الإسلام؟ وهل يجوز في مدة معينة، جزاكم الله خيراً؟","title":"حكم الإجهاض","answer":"الجواب: هذا فيه تفصيل، أمره عظيم، الإجهاض أمره عظيم وفيه التفصيل: إذا كان في الأربعين الأولى فالأمر فيه أوسع، إذا دعت الحاجة إلى الإجهاض لأن عندها أطفال صغار تربيهم ويشق عليها الحمل، أو لأنها مريضة يشق عليها الحمل فلا بأس بإسقاطه في الأربعين الأولى، أما في الأربعين الثانية بعد العلقة وفي الأربعين الثالثة المضغة هذا أشد، ليس لها إسقاطه إلا عند عذر شديد، مرض شديد، يقرر المختص أنه يضرها بقاؤه فلا مانع من إسقاطه في هذه الحالة، عند خوف الضرر الكبير.\nوأما بعد نفخ الروح فيه بعد الشهر الرابع فلا يجوز إسقاطه أبداً، بل يجب عليها أن تصبر وتتحمل حتى تلد إن شاء الله، إلا إذا قرر طبيبان أو أكثر مختصان ثقتان أن بقاءه يقتلها وسبب لموتها فلا بأس بتعاطي أسباب لإخراجه حذراً من موتها؛ لأن حياتها ألزم، عند الضرورة القصوى بتقرير طبيبين أو أكثر ثقات أن بقاءه يضرها، وأن عليها خطراً بالموت إذا بقي فلا بأس، إذا وجد ذلك بالشروط المذكورة فلا حرج في ذلك إن شاء الله، وهكذا لو كان مشوهاً تشويهاً يضرها لو بقي يكون خطر عليها، قرر طبيبان فأكثر أن هذا الولد لو بقي عليها خطر الموت لأسباب في الطفل، فهذا كله يجوز عند الضرورة إذا كان عليها خطر.. خطر الموت، بتقرير طبيبين أو أكثر مختصين ثقتين. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8598/حكم-الاجهاض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31706.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":10601,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10610,"question":"هل يجوز للمرأة أن تتعاطى علاجاً يمنع عنها العذر الشرعي إذا كانت تريد الحج؟","title":"حكم تعاطي المرأة علاجاً يمنع الحيض في الحج ورمضان","answer":"الجواب: لا أعلم مانعاً من ذلك، تتعاطى ما يمنع الحيض في حال الحج أو العمرة أو في شهر رمضان حتى تصوم مع الناس كل هذا لا حرج فيه إن شاء الله نعم، إذا كان لا يترتب عليه ضرر، إذا كانت الحبوب التي تتعاطاها لا يترتب عليها ضرر. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8777/حكم-تعاطي-المراة-علاجا-يمنع-الحيض-في-الحج-ورمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32604.mp3","categories":["الحيض والنفاس","الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":10735,"question":"المستمعة (أ. ع. أ) من تعز في اليمن بعثت برسالة -مطولة بعض الشيء- تقول: إني أم لثلاثة أطفال ومشكلتي هي: أني عندما أكون حاملاً أمرض مرضاً شديداً، وهذا المرض يستمر لمدة ستة أشهر، فأبقى في غرفتي وأعتزل عن كل شيء، وأصبح عالة على أهلي، حيث يقوموا على خدمتي أنا وأولادي، ولا أريد أن أشاهد أحداً ولا أحب أي طعام له رائحة، حتى أولادي لا أريد أن أسمع أصواتهم، حتى إني قمت بفطم ابنتي وهي لم تبلغ السنتين من شدة المرض، وكذلك لا أريد النور في غرفتي التي أنا فيها في هذه الحالة، هل يجوز والحال ما ذكرت أن أمنع الحمل نهائياً، علماً أني أسقطت بعد أن كان لي سبعة أشهر؟ جزاكم الله عني وعن المسلمين خيرا.","title":"حكم امتناع المرأة عن الحمل بسبب الضرر، وحكم إسقاط الجنين","answer":"الجواب: نعم لا حرج عليك في استعمال الحبوب ونحوها التي تمنع الحمل؛ لأن هذا ضرر عظيم ومشقة كبيرة، والله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ويقول جل وعلا: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فلا حرج عليك في استعمال الحبوب ونحوها مما يمنع الحمل لهذه المضرة العظيمة، لكن إذا حملت فليس لك إسقاط ذلك بعدما يتجاوز الأربعين الأولى، وأما في الأربعين الأولى فالأمر في هذا أوسع إذا كان هناك بعض المضرة، أما استعمال ما يمنع الحمل بالكلية من أجل هذه المضرة فلا حرج في ذلك.\nلكن لو قدر أنك تساهلت حتى صار الولد إلى ما بعد الأربعين فلا تسقطيه بل تحملي وتصبري لعل الله أن يجعل في ذلك الخير والبركة. نعم.\nالمقدم: جزاكم الله خيراً، قلتم: أربعين سماحة الشيخ، والذين قالوا: ثمانين ما رأيك في ذلك؟\nالشيخ: لا ... أربعون لأنها وقت النطفة كالعزل وقت النطفة كالعزل كما يعزل عنها، أما إذا انتقل إلى العلقة أو إلى المضغة صار انتقل إلى حيوان حينئذٍ إلى أصل حيوان، فالواجب ترك ذلك إلا عند الضرورة القصوى إذا صار هناك ضرر بين عظيم فلا بأس بواسطة الطبيبات المختصات أو الطبيب المختص إذا لم يوجد طبيبة مختصة بإسقاطه عند الضرر ... يعني: إذا كان يخشى عليها الهلكة والموت. نعم.\nالمقدم: هذا في حال الثمانين؟\nالشيخ: بعد الأربعين.\nالمقدم: بعد الأربعين.\nالشيخ: أما إذا تخلق ونفخت فيه الروح بعد الأربعة الأشهر، فهذا أشد ليس لها إسقاطه إلا إذا قرر الأطباء أن عدم إسقاطه وعدم إخراجه يكون سبباً لموتها فحياتها مقدمة، لا بأس بإسقاطه بالطريقة الممكنة عند الأطباء حتى لا تموت هي بأسباب بقائه ....","link":"https://binbaz.org.sa/fatwas/8917/حكم-امتناع-المراة-عن-الحمل-بسبب-الضرر-وحكم-اسقاط-الجنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34508.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":11408,"question":"هذا السائل (أبو عبدالرحمن . س. ع. س) منطقة سدير يقول في هذا  لقد انتشرت في الآونة الأخيرة استعمال مانع الحمل بعد الزواج، وذلك لكي تعرف الزوجة سلوكيات الزوج، فإن كانت صالحة؛ تركت الحبوب، وإن كان العكس؛ استمرت حتى يكون الطلاق، والمقصود من ذلك مشكلة الولد بينهما، فما هو الحل الصحيح في ذلك في حكم الشرع في نظركم؟ جزاكم الله خيرًا.","title":"حكم استعمال موانع الحمل حتى تطمئن لأخلاق الزوج","answer":"الجواب: استعمال الحبوب بهذا القصد لا أعلم له أصلًا، والمشروع ترك ذلك؛ لأن الله قد يرزقهما ولدًا يكون سببًا للألفة والمحبة واستمرار النكاح، فلا أرى وجهًا لاستعمال الحبوب في أول الزواج، بل السنة أن تدع ذلك، والمشروع أن تدع ذلك. وفي حل هذا نظر -في حل استعمال الحبوب نظر- بل المشروع أن تترك ذلك؛ لعل الله يرزقهما ولدًا؛ فيكون سببًا للمحبة والوئام بينهما، إلا من علة، أن يكون هناك علة شرعية، كأن تكون مريضة يضرها الحمل، أو أسباب أخرى يخشى منها المضرة، أما لهذا القصد لتعرف حال الزوج، فالذي يظهر لي من الشرع عدم استعمال هذه الحبوب، وحسن الظن بالله، ولعل الله يرزقهما ولدًا يكون سببًا للوئام والاجتماع وبقاء النكاح. والمقصود يقول الرسول ﷺ قال: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة فالرغبة في المولود أمر مطلوب، وسوء الظن لا وجه له، بل تحسن ظنها بالله، وتترك استعمال الحبوب، ولعل الله يجعل في ذلك الخير، والبركة.","link":"https://binbaz.org.sa/fatwas/9591/حكم-استعمال-موانع-الحمل-حتى-تطمىن-لاخلاق-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29319.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":12300,"question":"هل يجوز استعمال الحبوب المانعة للحمل؛ إذا كان أخذها بموافقة الزوج، وليس القصد من أخذها مخافة الفقر، أو قلة الرزق؛ لأن الرزق على الله  ولكن لتنظيم النسل، وليس لتحديده؟","title":"حكم استعمال حبوب المنع من الحمل لقصد التنظيم","answer":"الجواب:  لا حرج في ذلك إذا كان برضا الزوج عند الحاجة إلى ذلك؛ لكثرة الأولاد، أو لكونها تتألم كثيرًا، أو لأسباب معقولة تضر المرأة؛ فلا بأس بتنظيمه بالحبوب حتى لا يضرها الحمل، وحتى لا يضرها في التربية أيضًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10500/حكم-استعمال-حبوب-المنع-من-الحمل-لقصد-التنظيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45306.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":12330,"question":"إحدى الأخوات من الجزائر بعثت برسالة وضمنتها جمعًا من الأسئلة، في أحد أسئلتها تسأل عن حبوب منع الحمل، هل يجوز استعمالها، أو لا؟ جزاكم الله خيرًا.","title":"حبوب منع الحمل، هل يجوز استعمالها أم لا؟","answer":"الجواب:  هذه فيها تفصيل: إذا كان هناك مضرة، لأن معها طفل ترضعه، وتريد أن ترضعه، وألا تحمل عليه، ورضي الزوج بذلك؛ فلا بأس، أو كان يعني: يضرها الحبل، عندها مرض، ويضرها الحمل، فلا بأس أن تتعاطى الحبوب مؤقتًا حتى يزول المرض والأذى. أما تعاطيها لكراهة الأولاد، أو خوف المشقة من نفقتهم هذا لا يجوز. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10528/حبوب-منع-الحمل-هل-يجوز-استعمالها-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39814.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":12600,"question":"من اليمن الجنوبي محافظة عدن المستمعة (م. ع. ن) بعثت برسالة تقول فيها: أنا سيدة مسلمة -والحمد لله- أؤدي الواجبات التي فرضها علي ربي من صلاة وصيام وزكاة، ولكني توقفت عن الإنجاب في فترة كان زوجي فيها مريضًا بالسل، وكانت هذه الفترة حوالي عشر سنوات، وبعدها توقفت عني الدورة نهائيًا، فهل في فعلي هذا شيء يغضب الله علي ذلك بأن أولادي كانوا يصابون بشلل نصفي، ومنهم من يتوفى، ومنهم من يبقى على قيد الحياة وهو مصاب بهذا المرض؟ أفيدوني أفادكم الله.","title":"حكم توقف المرأة عن الإنجاب بسبب مرض الزوج","answer":"الجواب:  إذا كنت فعلت ما يمنع الإنجاب برضا الزوج؛ فلا حرج عليك إذا كان برضاه، أو موافقته، نرجو ألا يكون عليك حرج، أما إذا كان ذلك بغير رضاه، وبغير علمه، فالواجب عليك التوبة والاستغفار، والندم على ما مضى، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، إذا كانت المرأة سماحة الشيخ! لا تلد إلا مواليد مصابين بعاهات معينة، هل لها أن توقف الإنجاب؟ الشيخ: ما يظهر لنا؛ لأن الله -جل وعلا- قدير على كل شيء، قدير، يعطيها أولادًا سالمين، ولكن لا مانع من العلاج، تتصل بالأطباء المختصين، قد يكون مرضها في الرحم تعطى علاجًا له، ولكن لا يجوز لها الامتناع، وإن كانت المرأة المذكورة إن كانت مما تعاطت الحبوب من أجل هذا؛ فعليها الاستغفار أيضًا، كأنها ما امتنعت من ذلك إلا خشية أن يكون هناك شلل، أو كذا؛ فينبغي لها التوبة من ذلك؛ لأن الأمر لا يستمر، بل قد يقع هذا سليم، وهذا مصاب، وهذا طيب، وهذا مصاب بمرض آخر. الحاصل: أن كونها تتعاطى ما يمنع الحمل من أجل خوف الشلل، أو خوف كذا لا يجوز لها ذلك؛ لأن الله قد شرع للعباد أن يتعاطوا أسباب النسل، وأن يجتهدوا في تكثير الأمة، ولما في هذا من الخير العظيم للجميع. وأما إن كان لا، أنها امتنعت من أجل السل الذي في زوجها، ومخافة أن يصيبها السل؛ فهذا لا ينبغي لها أيضًا، وعليها أن تتوب إلى الله، وتستبيح زوجها إن كان قد منعها من ذلك، أما إن كان برضاه؛ فالأمر في هذا واسع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10809/حكم-توقف-المراة-عن-الانجاب-بسبب-مرض-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41312.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":12921,"question":"المستمعة (م. م) مصرية تعيش في الطائف بعثت برسالة ضمنتها جمعًا من الأسئلة من بينها سؤال يقول: هل يجوز للزوجين استخدام طريق العزل إذا كانا يريدا أن يؤخرا الإنجاب حتى فطام الطفل الأول؟","title":"هل يجوز العزل حتى يؤخر الإنجاب حتى فطام الطفل الأول؟","answer":"الجواب:  لا حرج في ذلك، النبي ﷺ أقر العزل، ولكن العزل لا يمنع ما أراد الله من الولد، قد يسبق الماء، ويغلب الرجل على ذلك، إذا أراد الله الولد قد يسبق الماء، ولو قليلًا من الماء؛ فيحصل منه الولد، لكن العزل لا حرج فيه، قال جابر : كنا نعزل والقرآن ينزل، فبلغ ذلك النبي ﷺ فلم ينهنا، عليه الصلاة والسلام.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11136/هل-يجوز-العزل-حتى-يوخر-الانجاب-حتى-فطام-الطفل-الاول ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46906.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":12922,"question":"تسأل وتقول: هل يجوز استعمال حبوب منع الحمل بدلًا من العزل لمدة عامين حتى يتم فطام الطفل الأول، مع العلم بأن الأم ليس بها أي مرض، ولكنها تريد إرضاع طفلها لمدة عامين؟","title":"هل يجوز استعمال حبوب منع الحمل بدلاً من العزل؟","answer":"الجواب:  لا ينبغي استعمال الحبوب؛ لأنها تضر، وتسبب امتناع الولد، أما العزل فهو أسهل؛ لأنه قد يسبق الماء، ويحصل الولد، أما استعمال الحبوب ونحوها؛ فلا ينبغي إلا من مضرة، كأن يكون عندها أولاد كثيرون تعجز عن خدمتهم، وتربيتهم؛ فلا بأس أن تستعمل الحبوب بعد استشارة الطبيب المختص، وتقريره عدم مضرتها، مع رضا زوجها بذلك. وأما إذا كان ما هناك مضرة، سليمة، ورحمها سليم، وليست مريضة، وليس عندها أولاد كثيرون يشق عليها تربيتهم؛ فلا ينبغي في هذه الحال، ولا يجوز استعمال الحبوب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11137/هل-يجوز-استعمال-حبوب-منع-الحمل-بدلا-من-العزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46907.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":13210,"question":"يقول هذا السائل فهد عبدالله من الجمهورية اليمنية يقول: ما حكم استعمال لولب منع الحمل بالنسبة للنساء، وهل استعماله حرام، ومعارض لحكم الله في إنجاب الأطفال، وبماذا تنصحون من سمح لزوجته أن تستعمل مثل هذا اللولب؟","title":"حكم استعمال لولب للنساء بغرض منع الحمل","answer":"الجواب: استعمال اللولب والحبوب لا يجوز لمنع الحمل، المطلوب طلب النسل، المطلوب من الزوجين أن يحرصا على طلب النسل، وكثرة الأولاد، وتكثير الأمة، كما قال ﷺ: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة لكن إذا كان لعلة كمرض يشق معه الحمل، وتراضت هي وزوجها على ذلك، أو لحاجة الطفل لحليبها، والحمل يمنع هذا اللبن، وهي تحتاج إلى أن ترضع طفلها؛ فلا بأس أن تستعمل الحبوب، أو اللولب لأجل المصلحة الشرعية، أو لأجل دفع المضرة التي عليها، أما بدون مضرة، وبدون مصلحة؛ فلا يجوز، بل الواجب ترك ذلك، وأن يحسن الظن بالله  وأن الرزق عند الله ولو جاءهم عشرون، أو ثلاثون، أو أكثر، الرزق عند الله، وهذا خير لهم، تكثير الأمة تكثير لعباد الله الصالحين، نسأل الله أن يصلح لهم الذريات، ووجود الذرية الصالحة خير لهم وللمسلمين. فعليهم أن يحسنوا الظن بالله، وأن يدعوا الله أن يصلح لهم الذريات، وأن يدعوا الحبوب واللولب كذلك إلا من مصلحة شرعية، أو مرض حادث بها يضرها وجود الحمل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11484/حكم-استعمال-لولب-للنساء-بغرض-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52003.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":14810,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع: (ع. م. ي. م) من السودان، حيث بعث برسالة مطولة، عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة يسأل ويقول: نحن نسكن في الريف بعيدًا عن المدينة، ولدينا أبناء صغار وبنات، بحاجة إلى تعليم وعلاج، ونعاني كثيرًا من تأمين هذه المتطلبات، فهل يجوز لنا أن نجعل النساء يستعملن حبوب منع الحمل لتنظيم الأسرة، أم كيف توجهوننا؟ جزاكم الله خيرًا.","title":"حكم استعمال حبوب منع الحمل لتنظيم الأسرة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فاستعمال ما يمنع الحمل، أو ينظم الحمل بين أوقاتٍ وأوقات، بسبب ما ذكره السائل لا وجه له، ولا ينبغي هذا، بل ينبغي لكم أن تجتهدوا في القرب من محلات الحاجة، التي تشكون منها، كالمدارس، أو المستشفيات، أو نحو ذلك؛ لأن الرسول -عليه الصلاة والسلام- رغب الأمة في تكثير النسل، وقال: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة فالنبي ﷺ حث على تكثير النسل، فلا ينبغي التساهل في هذا الأمر، وفي إمكانكم علاج الوضع بغير ذلك من القرب من محلات الأطباء، بالقرب من المدارس، إيجاد مدرسة عندكم، التعاون في إيجاد طبيب عندكم، إلى غير هذا من الأسباب، يعني: إيجاد وسائل وأسباب غير ما ذكرتم من تعاطي منع الحمل، أو تنظيمه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13299/حكم-استعمال-حبوب-منع-الحمل-لتنظيم-الاسرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64201.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":14853,"question":"إذا أجهضت المرأة عامدة متعمدة فما الحكم؟","title":"حكم الإجهاض تعمدًا","answer":"الجواب: لا يجوز لها ذلك، لا يجوز لها الإجهاض.  وفيه تفصيل: إذا كان بعد التخلق بعد أربعة أشهر كان محرمًا، كان قتلًا هذا نعوذ بالله، إذا كان بعد أربعة أشهر قتلًا، وهذا محرم عظيم، ومنكر كبير، نسأل الله العافية.  أما إذا كان قبل ذلك فهو أسهل، ولا يجوز لها ذلك، لا في الشهر الرابع، ولا في الثالث، ولا في الثاني، لكن في الأربعين الأولى إذا دعت المصلحة والحاجة لإسقاطه في الأربعين الأولى لمشقة عليها، ونحو ذلك، فلا بأس بذلك، أما في الأربعين الثانية أو بعدها فلا يجوز إلا لعلة يقررها الأطباء، يخشى عليها من بقائه فيها، هذا فيه تفصيل يحتاج إلى تقرير من طبيبين، أو أكثر مختصين فيما يتعلق بضرر البقاء في رحمها، والحاجة إلى إسقاطه وإجهاضها هذا يحتاج إلى تفصيل، لكن بعد أربعة أشهر هذا لا يجوز أبداً؛ لأنه قتل.\nالمقدم: يعتبر قتل. الشيخ: قتل، لا يجوز حتى ولو قال الأطباء: يسقط، لا يجوز. المقدم: وأقل من أربعة أشهر لا يعتبر قتل؟\nالشيخ: لا يعتبر قتل؛ لأنه ما بعد نفخت فيه الروح، لكن تخلقت.. تخلق بعد الأربعين، بعد الأربعين، لا يجوز لها الإجهاض، لا في الأربعين الثانية، ولا في الثالثة، وعليها التحمل والصبر، ولعل الله يجعل في ذلك الخير الكثير، لكن إذا كان هناك مضرة وخطر عليها تراجع الأطباء حتى يقرروا شيئًا يعتمد عليه، ويترتب عليه الفتوى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13345/حكم-الاجهاض-تعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63824.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":14855,"question":"إذا أجهضت المرأة عامدة متعمدة فما الحكم؟","title":"حكم الإجهاض تعمدًا","answer":"الجواب: لا يجوز لها ذلك، لا يجوز لها الإجهاض.  وفيه تفصيل: إذا كان بعد التخلق بعد أربعة أشهر كان محرمًا، كان قتلًا هذا نعوذ بالله، إذا كان بعد أربعة أشهر قتلًا، وهذا محرم عظيم، ومنكر كبير، نسأل الله العافية.  أما إذا كان قبل ذلك فهو أسهل، ولا يجوز لها ذلك، لا في الشهر الرابع، ولا في الثالث، ولا في الثاني، لكن في الأربعين الأولى إذا دعت المصلحة والحاجة لإسقاطه في الأربعين الأولى لمشقة عليها، ونحو ذلك، فلا بأس بذلك، أما في الأربعين الثانية أو بعدها فلا يجوز إلا لعلة يقررها الأطباء، يخشى عليها من بقائه فيها، هذا فيه تفصيل يحتاج إلى تقرير من طبيبين، أو أكثر مختصين فيما يتعلق بضرر البقاء في رحمها، والحاجة إلى إسقاطه وإجهاضها هذا يحتاج إلى تفصيل، لكن بعد أربعة أشهر هذا لا يجوز أبداً؛ لأنه قتل.\nالمقدم: يعتبر قتل. الشيخ: قتل، لا يجوز حتى ولو قال الأطباء: يسقط، لا يجوز. المقدم: وأقل من أربعة أشهر لا يعتبر قتل؟\nالشيخ: لا يعتبر قتل؛ لأنه ما بعد نفخت فيه الروح، لكن تخلقت.. تخلق بعد الأربعين، بعد الأربعين، لا يجوز لها الإجهاض، لا في الأربعين الثانية، ولا في الثالثة، وعليها التحمل والصبر، ولعل الله يجعل في ذلك الخير الكثير، لكن إذا كان هناك مضرة وخطر عليها تراجع الأطباء حتى يقرروا شيئًا يعتمد عليه، ويترتب عليه الفتوى، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13345/حكم-الاجهاض-تعمدا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63824.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":14863,"question":"من طرابلس المستمع محمد عمار نجار، من جامعة الفاتح، بعث يسأل ويقول: ما حكم الدين الإسلامي في تنظيم النسل عن طريق استخدام حبوب منع الحمل، أو اللولب، أو غير ذلك من الطرق الأخرى؟جزاكم الله خيرًا، وما الحكم في منع الحمل نهائيًا بعد عدد معين من الأطفال؟","title":"حكم منع الحمل نهائيا بعد عدد معين من الأطفال","answer":"الجواب: أما تنظيم النسل فلا بأس به إذا دعت إليه الحاجة؛ لكونها ذات أطفال كثيرين، ويشق عليها التربية، أو لأنها مريضة، أو لأسباب أخرى رآها الأطباء الثقات، فلا مانع من التنظيم بأن تمنع الحمل سنة أو سنتين، وهكذا حتى تستقيم، حتى تستطيع تربية أطفالها، أو حتى يخف عنها المرض.  أما بدون حاجة فلا، فلا ينبغي أخذ الحبوب، ولا ينبغي منعه؛ لأن الله -جل وعلا- شرع لنا أسباب تكثير النسل؛ ولأن الحمل من فضل الله على العبد، وهو يأتي برزقه، وفي تربيته والتعب عليه أجر كثير مع صلاح النية، فلا حاجة إلى أخذ الحبوب، ولا إلى التنظيم، إلا إذا كان هناك مصلحة، وحاجة تقتضي ذلك ككثرة الأولاد، ومشقة التربية، أو ما يعتريها من المرض، يعتري الأم من المرض، أو نحو ذلك من الأسباب الوجيهة، سواءً كان بالحبوب أو باللولب أو بإبر أو غير ذلك من أسباب تنظيم الحمل. أما منعه فلا يجوز منعه بالكلية إلا لعلة، إذا كان الحمل فيه خطر على حياتها، وذكر الأطباء أن الحمل فيه خطر عليها فلا بأس بمنعه، وإلا فلا يمنع، ولا يجوز لها تعاطي منعه؛ لأنها مشروع لها أن تلتمس الأولاد، وأن تتزوج، وزوجها كذلك مشروع له التماس الأولاد، وقد تفعل هذا، وتندم ندمًا كثيرًا. فالحاصل: أنه لا يجوز تعاطي منع الحمل إلا لعلة لا حيلة فيها، وهي الخوف عليها من الموت؛ لأن الحمل فيه خطر على حياتها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13375/حكم-منع-الحمل-نهاىيا-بعد-عدد-معين-من-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64518.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":14952,"question":"هذه وردتنا هذه الرسالة من أحد المستمعين وهو سعد صالح الفجري، من العيون بالأحساء، يقول: كثير من الناس يؤيد تحديد النسل، وذلك عندما يرزقه الله عدة أولاد، ويكتفي ويعطي زوجته حبوب منع الحمل، يقول: نريد نصيحة المسلمين، ونصيحتنا عامة بذلك، حيث أنني أعتقد أن ذلك من التشبه بالغرب ومن أعمال الغرب.","title":"ما حكم تحديد النسل وتنظيمه؟","answer":"الجواب: لا شك أن تحديد النسل أمر لا يجوز، وفيه مضار كثيرة: إضعاف للأمة، وتقليل لعددها، والشريعة جاءت بالحث على أسباب التوالد والترغيب في ذلك، ومن ذلك قوله -عليه الصلاة والسلام-: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة وفي لفظ: مكاثر بكم الأنبياء يوم القيامة فتزوج الولود مما حث عليه الشارع؛ ولأن في كثرة الأولاد تكثير الأمة العابدة لله وحده من المسلمين.  وفيه أيضًا ربما دعوا له دعوا لوالدهم فيستفيد من ذلك، وربما قاموا بأعمال جليلة تنفع المسلمين من طلب العلم ومن أعمال تنفع الأمة في عاجل أمرها وآجله، فيكون له في ذلك خير كثير إذا صلحت نيته وساعدهم على هذا الخير، أو دعا لهم بما يعينهم على هذا الخير. فالمقصود: أنه على خير والأمة على خير، إذا كثروا وصلحوا، والتوفيق بيد الله، إنما عليك فعل الأسباب والتوجه إلى الله بطلب الهداية لهم، والتوفيق لهم، مع الأخذ بالأسباب التي تسبب هدايتهم: من حسن التربية والتوجيه والملاحظة والعناية والأخذ على يد السفيه، إلى غير ذلك. فلا يجوز تحديد النسل؛ ولأن الموجودين ربما ماتوا، قد يحدد وعنده ثلاثة أو أربعة أو خمسة يموتون؛ فيندم غاية الندامة، فلا وجه للتحديد، لكن إذا دعت الحاجة إليه أو الضرورة لكون المرأة مريضة يضرها الحمل بتقرير الأطباء، أو لأنها تلد هذا على هذا بسرعة فيشق عليها تربيتهم؛ فأعطاها ما يمنع الحبل سنة أو سنتين حتى تستطيع التربية والقيام على شئون الأولاد، فهذا لا بأس به بصفة مؤقتة، نعم.","link":"https://binbaz.org.sa/fatwas/13450/ما-حكم-تحديد-النسل-وتنظيمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_648/nour_64802.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":15227,"question":"الرسالة الأخيرة في لقائنا هذا وردتنا من المرسل عبداللطيف عبدالله من الدلم بالخرج، يقول: إن زوجتي مصابة بمرض السكر، وعندها مرض ضغط الدم، فقرر الطبيب المختص أن الحمل عليها منه ضرر كبير، أو يكون خطر عليها، وعلى الجنين أيضًا، وحبوب منع الحمل تضرها، وتسبب مضاعفات أخرى، وقال: ما فيه إلا حالتين فقط:الأولى: قفل أو قلب الرحم.والثانية: العزل، أفيدوني بالأصلح، جزاكم الله عني خير الجزاء.","title":"حكم منع الحمل إذا كان فيه ضرر على المرأة","answer":"الجواب:  إذا تيسر دواء يغني عن قلب الرحم هذا أولى؛ لأنها قد تحتاج إلى الولد، وقد يزول الأذى، ويطيب المرض، فتحتاج إلى الولد، فينبغي العلاج بما يزيل الضرر، أو يخفف الضرر من دون قلب الرحم، حتى لا يفوتها الولد لو رغبت في ذلك.  وإذا كفى العزل في بعض الأحيان هذا طيب، العزل لا بأس به، أو دواء آخر غير العزل يمنع من الحمل منعًا مؤقتًا حتى يزول الأذى، ويزول المرض، فهذا أولى.  أما الشيء الذي يقطع الحمل مرة واحدة، فهذا ينبغي أن لا يفعل إلا عند الضرورة، نعم.","link":"https://binbaz.org.sa/fatwas/13729/حكم-منع-الحمل-اذا-كان-فيه-ضرر-على-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66807.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":15235,"question":"يقول أيضًا: بعض النساء يشربن حبوب منع الحمل، أفيدونا هل هذا حلال أم حرام؟","title":"حكم تعاطي المرأة حبوب منع الحمل","answer":"الجواب:  هذا فيه تفصيل: إذا كانت المرأة قد شق عليها الحمل؛ لأنها تحمل هذا على هذا، أو بها مرض يضرها الحمل على قول أهل الخبرة من الأطباء فلا بأس أن تأخذ الحبوب المانعة من الحمل بصفة مؤقتة، لا دائمًا، بل بصفة مؤقتة مثل سنة، سنتين حتى يتيسر لها تربية الأطفال، والقيام على الأطفال، أو حتى يزول المرض إن كان بها مرض.  أما أخذ الحبوب دائمًا فلا؛ لأن هذا معناه قطع النسل، وهذا شيء يخالف الشريعة، والشرع يتشوف للأولاد؛ ولهذا جاء في الحديث الشريف عنه -عليه الصلاة والسلام- أنه قال: تزوجوا الولود الودود، فإني مكاثر بكم الأمم يوم القيامة وفي لفظ: مكاثر بكم الأنبياء يوم القيامة فهذا يدل على أن الشرع يرغب في تكثير الأولاد والإحسان إليهم، وتربيتهم التربية الصالحة، حتى يكونوا مكثري الأمة الإسلامية، وحتى يكونوا مكثرين أيضًا لأجر محمد -صلى الله عليه وسلم-، فإنه كلما زاد أتباعه زاد أجره -عليه الصلاة والسلام-، فإن له بمثل أجور من اتبعه من أمته -عليه الصلاة والسلام-.  فينبغي للمؤمن أن يحتسب الأجر في استكثاره من الأولاد، ويتزوج الولود من النساء حتى يكثر أولاده، والله يعينه عليهم، والرزاق هو الله . لكن إذا كان هناك ضرورة من أجل مرض، مرض الرحم، أو مرض آخر يشق معه الحمل، أو كونها تحمل هذا على هذا يعني: يتوالى الحمل عليها، ويشق عليها، فلا مانع أن تأخذ بعض الحبوب للراحة، وتخفيف الأثر عليها من جهة مرض الرحم، أو غيره، أو من جهة حمل هذا على هذا، تكون فترة خفيفة سنة أو سنتين مدة الرضاع مثلًا أو أقل منها، نعم.","link":"https://binbaz.org.sa/fatwas/13736/حكم-تعاطي-المراة-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_673/nour_67304.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":15786,"question":"تسأل أم أنس فتقول: هل يجوز استخدام حبوب منع الحمل بقصد التنظيم لفترة معينة؟","title":"هل يجوز استخدام حبوب منع الحمل بقصد التنظيم لفترة؟","answer":"الجواب: إذا دعت الحاجة إلى ذلك، كأن يكون عندها أطفال كثيرون، ويشق عليها أن تحمل في وقت الرضاعة، ورضي الزوج بذلك فلا حرج، إذا كان فيه مصلحة، ودفع مضرة في أيام الرضاعة، أو كانت يضرها الحمل بالتتابع حتى يكون بينهما فجوة سنتين أو أكثر دفعًا للمضرة، ورضي الزوج بذلك فلا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14376/هل-يجوز-استخدام-حبوب-منع-الحمل-بقصد-التنظيم-لفترة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74213.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":15797,"question":"يقول: استعملت زوجتي وسيلة لتنظيم النسل؛ وذلك لكونها أرهقت بالإنجاب المتتالي كل عام، وقد عزمت أنها بعد مرور خمسة أعوام ستترك هذه الوسيلة، علمًا بأنها قد وضعت أربعة أطفال، أكبرهم عنده أربع سنوات ونصف، فما هو رأي توجيهكم؟جزاكم الله خيرًا.","title":"القول في استعمال وسيلة لتنظيم الحمل","answer":"الجواب: لا حرج في استعمال وسائل تنظيم النسل إذا دعت الحاجة إلى ذلك دفعًا للضرر، ولكن يكون ذلك بوقت الرضاع في السنة الأولى والسنة الثانية، حتى لا يضرها الحمل المتتابع، وحتى لا يمنع من التربية الشرعية لأطفالها، فإذا كانت تضررت بالحمل على الحمل في تربية الأولاد وفي صحتها فلا حرج من التنظيم في حدود السنة والسنتين أيام الرضاع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14387/القول-في-استعمال-وسيلة-لتنظيم-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74303.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":16548,"question":"يسأل في سؤال مطول عن أولئك الذين يجرون بعض العمليات للنساء من أجل تحديد النسل، ويسأل عن حكم تحديد النسل في الإسلام؟","title":"حكم تحديد النسل في الإسلام","answer":"الجواب: لا يجوز تحديد النسل، بل ينبغي للرجل، والمرأة الحرص على المزيد من الذرية؛ لأن الرسول  قال: تزوجوا الولود الودود؛ فإني مكاثر بكم الأنبياء يوم القيامة وفي اللفظ الآخر: فإني مكاثر بكم الأمم يوم القيامة فالرسول ﷺ حث على تزوج الولود الودود، ثم المؤمن ينبغي له أن يحرص على أن يكون له ذرية صالحة تنفعه في الدنيا، وتنفعه في الآخرة، تكثر جمع المسلمين، ويحرص على الزوجة الصالحة، وعلى العناية بالذرية، وأن يربيهم التربية الإسلامية الطيبة، فتحديد النسل لا وجه له. ومعنى تحديد النسل، يعني: أن يتفق مع المرأة على عدد معلوم، لا، بل يجتهد مع المرأة جميعًا أن الله يعطيهما المزيد من الذرية على وجه لا يضرها، فإذا كان هناك ضرر، كونها تحمل هذا على هذا، وعليها ضرر؛ لا بأس أن تتعاطى أشياء تمنع الحمل وقتًا معينًا، مثل وقت الرضاعة، أو بعض وقت الرضاع حتى تقوى على التربية، لا بأس بهذا من غير أن يحدد النسل بعدد معلوم. لكن لا بأس أن تتعاطى أشياء تمنع الحمل وقتًا معينًا؛ دفعًا للضرر الذي عليها، وحرصًا على تربية الأولاد التربية الإسلامية، نعم. المقدم: جزاكم الله خيرًا، إذًا يدعو سماحتكم إلى التنظيم لا التحديد؟ الشيخ: نعم، التنظيم الذي يدعو له الضرورة، تدعو له الحاجة، والضرورة، والمصلحة الشرعية، أما التحديد لا. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15268/حكم-تحديد-النسل-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81502.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":16790,"question":"تقول عن نفسها: أنا مريضة، وشخّص الأطباء حالتي، وهي فتحة قلبية، وزوجي يريد أطفالًا، لكن خوفًا على صحتي بدأت أستعمل أقراص منع الحمل، فهل أنا على صواب، أم ماذا؟ جزاكم الله خيرًا.","title":"حكم استعمال حبوب منع الحمل بغير إذن الزوج","answer":"الجواب: هذا يحتاج إلى مراجعة أهل الخبرة من الأطباء، فإذا كان عليك مضرة، وخطر من ترك هذه الأقراص؛ فلا حرج، وإن كانت هذه الأقراص ليست بضرورية، ولم يرض زوجك بها؛ فاتركيها. والخلاصة: أن هذا يرجع إلى سؤال أهل الخبرة من الأطباء؛ فإن كنت في ضرورة إلى هذا؛ فلا بأس، وإن كان هناك غنية عنها، فالواجب تركها إلا أن يأذن الزوج في استعمالها، نسأل الله لنا ولك العافية. المقدم: جزاكم الله خيرًا، مع ملاحظة -سماحة الشيخ- أن الزوج هو ذلكم المسؤول عنه في السؤال الأول؟ الشيخ: وسبق ما دام هو الزوج المذكور، سبق أنك لا يجوز أن تعتبريه زوجًا ما دام بهذه الحالة، ولك أن تستعملي ما ينفعك، ويخفف الضرر عنك، وإن لم يرض؛ لأنه ليس بزوج في الحقيقة، ما دام يدع الصلاة، أو يتعاطى شيئًا آخر مما يوجب كفره من سب الدين، أو تعاطي أشياء أخرى من أنواع الكفر، أما شرب المسكر إذا لم يستحله، ولكن فعله، وهو يعلم أنه حرام، وفعله طاعة لهواه؛ فإنه يكون بذلك عاصيًا وفاسقًا، ولا يكون كافرًا، ولكن لك -كما تقدم- طلب الطلاق، أما إن استحله يرى أنه حلال، وأنه لا بأس به؛ يكون كافرًا بذلك نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15547/حكم-استعمال-حبوب-منع-الحمل-بغير-اذن-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76302.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":18068,"question":"رسالة وصلت إلى البرنامج من البحرين باعثتها إحدى الأخوات من هناك تقول: الحائرة (م. م. م) أختنا لها سؤال طويل، ملخص  أنه نتيجة لمتاعب الحمل والولادة والتربية تضطر للهروب عن زوجها نظرًا لتأثرها بالأدوية التي تؤخذ لتنظيم النسل، وترجو من سماحتكم النصح والتوجيه.","title":"حكم استخدام المرأة لأدوية منع الحمل","answer":"الجواب: نصيحتي لها أن تدع هذه الأدوية التي تنفرها من زوجها، وأن تتحمل الحمل والولادة ولعل في هذا خيرًا كثيرًا ومصالح جمة، فإن الأولاد إذا أصلحهم الله صار في ذلك خير لهم وخير لوالديهم جميعًا وخير للأمة، فينبغي لها أن تتحمل وتصبر وتدع الأدوية التي قد تؤذيها وتضرها إلا إذا كان هناك مرض أو تقرير من أطباء يدل على أن حملها هذا على هذا يضرها ويسبب أخطارًا كثيرة عليها، فإنها تتقيد بالتوجيهات الطبية ولو أخذت ما يمنع الحمل سنة أو سنتين أو أكثر على حسب توجيهات الطبيب المختص البصير الثقة في ذلك فلا مانع من تنظيم الحمل على هذا الوجه للمصلحة الشرعية ولدفع الضرر عنها وعن أولادها الصغار. أما لمجرد الترفه وطلب الراحة فهذا لا ينبغي ولا يجوز؛ لأن الرسول ﷺ حث الأمة على طلب النسل وتكثير الأمة، وقال عليه الصلاة والسلام: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة وفي بعض الروايات: الأنبياء يوم القيامة. فالرسول ﷺ رغب في كثرة الأولاد وأخبر أنه يكاثر بأمته يوم القيامة الأمم، فكثرة الأولاد عن الطريق الشرعي مع الصبر والتحمل فيه خير كثير، وقد ينفع الله بهم الأمة وينفع الله بهم والديهم إذا أصلحهم الله. فالمشروع للمرأة التحمل والتصبر حتى يكثر الأولاد من طريق الحلال ومن طريق الزوج الشرعي والحمد لله، إلا لعلة وضرر لابد منه فإن هذا لا بأس فيه، لا بأس أن تتعاطى ما يخفف عنها هذا الأثر وهذا الضرر من طريق الأطباء المختصين والطبيبات المختصات حتى يكون التنظيم على بينة وعلى بصيرة وعلى وجه شرعي. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17103/حكم-استخدام-المراة-لادوية-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90203.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":18069,"question":"ألاحظ أيضًا سماحة الشيخ أنه من بين الرسائل التي أمامي الآن رسالة وصلت إلى البرنامج من القنفذة، وباعثها أحد الإخوة هو (ع. ل) من القنفذة كما ذكرت، أخونا أيضًا يذكر أن زوجته على نفس المستوى يقول: إن أعطاها من هذه الأدوية التي تنظم الحمل؛ فإنها تتأذى منها، وإن بقيت بدون فهي تحمل عامًا وترضع عامًا آخر وصحتها متدنية جدًا.ويسألون: هل هناك طريقة شرعية تستخدمها المرأة، ولا تهرب من زوجها وتبقى عنده والحالة هذه؟","title":"حكم العزل لأجل تنظيم النسل","answer":"الجواب: نعم، إذا كانت تتضرر كما ذكر الزوج من الحمل، ويحصل لها بذلك مضار شديدة، أو على ولدها الصغير؛ فإنه لا مانع من أن يعزل عنها، العزل لا بأس به، وكان السلف يعزلون عند الحاجة إلى ذلك. أو يسأل عن دائه الطبيبات المختصات لعلهن يجدن شيئًا ما يضرها ينفعها ولا يضرها عند الحاجة والضرورة إلى ذلك، والعزل أمر متيسر إذا استطاعه الزوج، وإذا كتب الله شيئًا تم، ولو بشيء قليل من المني، لكن هذا من الأسباب، والتوفيق بيد الله . نعم.","link":"https://binbaz.org.sa/fatwas/17104/حكم-العزل-لاجل-تنظيم-النسل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90204.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":18344,"question":"السائلة في هذا السؤال (ش. م. أ)، تقول السائلة (ش. م. أ) تقول: بأنها امرأة ذات عيال عددهم سبعة، وهي تأخذ في هذه الفترة مانع الحمل لكي تستريح من التعب، والإرهاق، ولكن الزوج يصر على عدم أخذها لمانع الحمل، وقد استمرت في أخذ مانع الحمل دون علمه هل يجوز لها ذلك؟","title":"أخذ المرأة حبوب منع الحمل دون علم الزوج","answer":"الجواب: إذا كان عليها مشقة كبيرة فلا حرج، وإلا فالأفضل و الأحوط عدم ذلك؛ لأن النسل كل ما كثر فهو مطلوب تكثير الأمة، ولها أجر كبير في ذلك، إذا أحسنت التربية هي والزوج لهم أجر كبير، النبي  يقول: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة . فإذا تيسر الصبر على ذلك، والقوة؛ ففيه خير عظيم، من تكثير الأمة، وحصول الأولاد الذين ينفعون والديهم إن شاء الله إذا صلحوا، فالحاصل أنه إذا كان فيه مشقة كبيرة فلا حرج. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17411/اخذ-المراة-حبوب-منع-الحمل-دون-علم-الزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78320.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]},{"id":19077,"question":"سماحة الشيخ يقول السائل: ما حكم استعمال حبوب منع الحمل بالنسبة للنساء؟","title":"حكم استعمال حبوب منع الحمل","answer":"الجواب: إذا كانت الحبوب تنفع ولا تضر إذا كانت تنفع ولا تضر فلا بأس إذا اتفقت مع الزوج على منع الحمل لأسباب شرعية من مضرتها أو رضاعها أو نحو ذلك من الأسباب التي يتفقان عليها فتعاطي الحبوب التي لا ضرر فيها لا بأس، إذا تراضى عليه الزوجان لمصلحة شرعية. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18245/حكم-استعمال-حبوب-منع-الحمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88321.mp3","categories":["الطب والتداوي","تنظيم الحمل وموانعه","قضايا المرأة"]},{"id":19207,"question":"قضية مشابهة تمامًا سماحة الشيخ، يقول صاحبها: زوجتي حملت بعد أن أنجبت مولودها بثلاثة أشهر وعشرين يومًا، وقد تذمرت كثيرًا من ذلكم الحمل، وحللت طبيًا، فأفاد الأطباء أن الجنين في عشرين يومًا تقريبًا، وتسأل سماحة الشيخ: هل لها أن تتصرف بذلكم الجنين لتتمكن من تربية هذا المولود الذي فرحت به كثيرًا ولاسيما أنه لم يسبقه إلا بنات؟","title":"حكم إسقاط الجنين إذا كان عمره أقل من أربعين يومًا","answer":"الجواب: الأفضل عدم التعرض لإسقاطه؛ لأن الله جل وعلا قد يجعل فيه خيرًا كثيرًا؛ ولأن الرسول ﷺ حرض على كثرة النسل، وقال عليه الصلاة والسلام: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة، فاحتساب الأجر في تكثير الأولاد أمر مطلوب، لاسيما وليس عندها إلا طفل واحد، وليس عليها مرض، فالأولى بها والأفضل لها عدم التعرض لإسقاطه، فإن أسقطته في الأربعين لمصلحة تراها ووافق زوجها على ذلك فلا حرج، لكن الأفضل والأولى ترك ذلك، لما تقدم من المصلحة العظيمة، وتحقيق ما قاله النبي عليه الصلاة والسلام، لكن ما دام الجنين في الأربعين، لم يتجاوز الأربعين فالأمر فيه أسهل وأوسع، وترك إسقاطه أفضل. المقدم: جزاكم الله خيرًا. يقول سماحة الشيخ: إن له بنتين سبقتا هذا المولود، فلديه ثلاثة أطفال...؟ الشيخ: لا حرج، إذا كان فيه مشقة فلا حرج، وهذا من باب التنظيم ولاسيما في الأربعين أمره أسهل. نعم. المقدم: جزاكم الله خيرًا. لكن تنصحون بالصبر لعل الله ...؟ الشيخ: مهما أمكن الصبر فهو أفضل .... ونسأل الله أن يعينها.\nالمقدم: اللهم آمين ، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18395/حكم-اسقاط-الجنين-اذا-كان-عمره-اقل-من-اربعين-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_888/nour_88802.mp3","categories":["قضايا المرأة","تنظيم الحمل وموانعه"]}]
